/**
 * 段落级标注：章节阅读页（/reading/:chapterId）在用，下划线/荧光笔按整段记录。
 *
 * 沉浸式阅读页已经换成按字符区间的标注（readerAnnotations.ts），章节页这一轮
 * 保持原样，所以这套「段落下标 → 类型」的实现单独留在这里。
 *
 * 存储键沿用 inkflow.reader.annotations.<id>：章节 id（jane-eyre 之类）和书架
 * 书 id 不同名，两套数据不会互相串门；沉浸式阅读页首次打开旧书时会读同一个
 * 前缀做迁移，只认 sentence:/word: 开头的键，段落键不受影响。
 */
export type ReaderAnnotationType = "underline" | "highlight" | "sentence";
export type ParagraphAnnotations = Record<string, ReaderAnnotationType>;

const STORAGE_PREFIX = "inkflow.reader.annotations.";

export function loadParagraphAnnotations(id: string): ParagraphAnnotations {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(
      localStorage.getItem(`${STORAGE_PREFIX}${id}`) ?? "{}",
    );
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return {};
    }
    const annotations: ParagraphAnnotations = {};
    for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
      if (
        value === "underline" ||
        value === "highlight" ||
        value === "sentence"
      ) {
        annotations[key] = value;
      }
    }
    return annotations;
  } catch {
    return {};
  }
}

export function saveParagraphAnnotations(
  id: string,
  annotations: ParagraphAnnotations,
) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(`${STORAGE_PREFIX}${id}`, JSON.stringify(annotations));
  } catch {
    // 隐私模式写不进去，页面上的标注这一小段时间照常显示。
  }
}
